        Object.assign(g.style, {
          position: 'fixed', left: r.left + 'px', top: r.top + 'px', zIndex: 70, pointerEvents: 'none',
          fontSize: cs.fontSize, fontWeight: cs.fontWeight, fontFamily: cs.fontFamily, color: '#2b2350',
          background: a.w.ghostHtml != null ? 'none' : '#fff2a8', padding: '0 .15em', borderRadius: '.25em',
          boxShadow: a.w.ghostHtml != null ? 'none' : '0 6px 0 rgba(0,0,0,.2)',
        });
        g.dataset.dx = a.c0.x - r.left; g.dataset.dy = a.c0.y - r.top; // keep the grab offset
        a.wc = { x: r.left + r.width / 2 - a.c0.x, y: r.top + r.height / 2 - a.c0.y }; // pointer → word centre
        document.body.appendChild(g);
        a.ghost = g;
        a.w.el.classList.add('hidden-word');
