      const anchor = S.add({ e: '🤖', s: 140, x: 700, y: 270, z: 4, tap: (o) => S.say(o, `"${sg.text()}"`) });
      S.add({ html: svg(240, 70, `<rect x="6" y="6" width="228" height="58" rx="10" fill="#3a2a80" stroke="${INK}" stroke-width="5"/>`), x: 700, y: 360, z: 5, static: true });
      let swaps = 0;
