      S.add({ html: '', w: 14, h: 120, x: 500, y: 410, z: 4, static: true, style: { background: '#8a8fa8', border: `4px solid ${INK}` } });
      const guard = S.add({ html: topSvg(), x: 500, y: 600, z: 5, tap: (o) => S.say(o, `${sg.text()}.`) });
      let over = false;
