        if (t === 'POST') { guard.to({ sy: 1.12 }, 200); S.say(guard, "I'm a post now. Posts don't move."); return; }
        if (t === 'OPTS') return S.say(guard, 'I opt... to stay.');
        if (t === 'STOP') return S.say(guard, 'STOP.');
        guard.shake();
