          const door = (label, lx) => add({ html: svg(160, 240, `<rect x="6" y="6" width="148" height="228" rx="16" fill="#cfd6e3" stroke="${INK}" stroke-width="7"/><rect x="22" y="70" width="116" height="80" rx="10" fill="#fff" stroke="${INK}" stroke-width="5"/>
            ${T_(80, 130, 52, label, '#2b2f6e')}<circle cx="132" cy="190" r="10" fill="${GOLD}" stroke="${INK}" stroke-width="4"/>`), x: lx, y: 480, z: 4, data: { label }, id: 'w10-door-' + label, tap: (o) => tapDoor(o) });
          door('NOW', 750); door('SOS', 500); door('MON', 250);
