          mk({ html: svg(140, 40, `<ellipse cx="70" cy="20" rx="64" ry="14" fill="#fff" stroke="${INK}" stroke-width="6"/>`), x: 330, y: 645, z: 3, static: true });
          mk({ html: A.match(false, 30, 120), x: 330, y: 590, z: 4, rot: 10, tap: say(S, 'A used match.') });
