          TL.track(smoke, [[0.7, { op: 0, y: 520 }], [0.76, { op: 1, y: 500 }], [1, { op: 0, y: 380 }]]);
          TL.track(gust, [[0.55, { op: 0, x: 180 }], [0.62, { op: 1, x: 220 }], [0.72, { op: 0.6, x: 320 }], [0.78, { op: 0, x: 340 }]]);
