          const CX = 500, CY = 430, R = 230;
          // the ring: socket k at angle 36k (0 = up). Socket 0 is the gap.
          const ringSvg = () => svg(560, 560, `<circle cx="280" cy="280" r="${R}" fill="none" stroke="${INK}" stroke-width="22"/><circle cx="280" cy="280" r="${R}" fill="none" stroke="${LILAC}" stroke-width="12"/>
            ${Array.from({ length: 10 }, (_, k) => { const a = k * 36 * Math.PI / 180, x = 280 + Math.sin(a) * R, y = 280 - Math.cos(a) * R;
              return k === 0 ? `<circle cx="${x}" cy="${y}" r="30" fill="#fff" stroke="${INK}" stroke-width="5" stroke-dasharray="8 6"/>`
                : `<circle cx="${x}" cy="${y}" r="30" fill="${accent(k - 1)}" stroke="${INK}" stroke-width="5"/><circle cx="${x - 9}" cy="${y - 9}" r="8" fill="#fff" opacity=".8"/>`; }).join('')}`);
          orbs.forEach((o, i) => { if (i < 9) { const a = (i + 1) * 36 * Math.PI / 180; o.to({ x: CX + Math.sin(a) * R, y: CY - Math.cos(a) * R }, 700, 'ease-in-out'); } else o.to({ op: 0 }, 300); });
